import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{n,t as r}from"./ArticleLayout-DuxBGx9a.js";var i,a,o=e((()=>{i=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Contrôlé sans assurance : risques, amende et que faire tout de suite`,description:`Contrôlé sans assurance ? Amende de 500 € à 3 750 €, immobilisation possible. Les vrais risques et comment se mettre en règle en 5 minutes.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/controle-sans-assurance-risques-amende`,datePublished:`2026-06-02`,dateModified:`2026-06-02`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Contrôlé sans assurance : risques et amende`,item:`https://assutempo.fr/articles/controle-sans-assurance-risques-amende`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Quelle amende risque-t-on en roulant sans assurance ?`,acceptedAnswer:{"@type":`Answer`,text:`Une amende forfaitaire délictuelle de 500 € (400 € minorée, 1 000 € majorée) à la première constatation, jusqu'à 3 750 € devant le tribunal, et 7 500 € en cas de récidive dans les 5 ans.`}},{"@type":`Question`,name:`Perd-on des points pour défaut d'assurance ?`,acceptedAnswer:{"@type":`Answer`,text:`Non. Ce n'est pas une infraction à points, mais elle expose à des peines complémentaires comme la suspension de permis ou la confiscation du véhicule.`}},{"@type":`Question`,name:`La police peut-elle immobiliser ma voiture lors du contrôle ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, sur-le-champ. Sans régularisation, le véhicule peut être placé en fourrière au bout de 48 heures.`}},{"@type":`Question`,name:`Comment se remettre en règle rapidement ?`,acceptedAnswer:{"@type":`Answer`,text:`En souscrivant une assurance, y compris une assurance temporaire dès 1 jour, qui délivre une attestation immédiate.`}},{"@type":`Question`,name:`Le défaut d'assurance va-t-il sur mon casier judiciaire ?`,acceptedAnswer:{"@type":`Answer`,text:`En cas de condamnation par un tribunal, oui, généralement au bulletin n°1, accessible aux seules autorités judiciaires.`}},{"@type":`Question`,name:`Peut-on souscrire une assurance temporaire après un contrôle ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, en ligne en quelques minutes, avec une attestation immédiate par email.`}}]}],a={slug:`controle-sans-assurance-risques-amende`,seo:{title:`Contrôlé sans assurance : amende, risques et que faire`,description:`Contrôlé sans assurance ? Amende de 500 € à 3 750 €, immobilisation possible… Découvrez les vrais risques et comment vous mettre en règle en 5 minutes.`,canonical:`https://assutempo.fr/articles/controle-sans-assurance-risques-amende`,jsonLd:i},category:`Urgence`,readTime:`4 min`,updatedDate:`2 juin 2026`,author:`Evidence Assurances`,headline:`Contrôlé sans assurance : risques, amende et que faire tout de suite`,immediateAnswer:`Vous venez d'être contrôlé sans assurance, ou vous craignez de l'être ? Soyons clairs : rouler sans assurance est un délit, et la facture peut grimper de 500 € à 3 750 €. Mais la situation se règle vite. En souscrivant une assurance temporaire en ligne, vous obtenez une attestation immédiate, présentable sur-le-champ - et vous évitez l'essentiel des conséquences. Voici ce que vous risquez exactement, et quoi faire dans la foulée.`,sections:[{type:`text`,heading:`Conduire sans assurance : qu'est-ce que vous risquez vraiment ?`,paragraphs:[`La loi est nette (article L324-2 du Code de la route) : mettre en circulation un véhicule sans assurance responsabilité civile est un délit. À la première constatation, l'infraction est généralement traitée par une amende forfaitaire délictuelle de 500 €, minorée à 400 € si vous payez sous 15 jours, majorée à 1 000 € au-delà de 45 jours. Si l'affaire passe devant le tribunal correctionnel, l'amende peut atteindre 3 750 €. Et en cas de récidive dans les 5 ans, elle peut doubler jusqu'à 7 500 €.`,`Bon à savoir : le défaut d'assurance n'entraîne pas de retrait de points (ce n'est pas une infraction à points), mais une condamnation peut être inscrite au casier judiciaire (bulletin n°1).`]},{type:`checklist`,heading:`Les peines complémentaires possibles`,intro:`Au-delà de l'amende, le juge peut prononcer :`,items:[`Suspension du permis jusqu'à 3 ans`,`Interdiction de conduire certains véhicules pendant 5 ans`,`Stage de sensibilisation à la sécurité routière (à vos frais)`,`Confiscation du véhicule si vous en êtes propriétaire`],note:`Autant de raisons de régulariser sans attendre.`},{type:`text`,heading:`Et votre véhicule ? Immobilisation et fourrière`,paragraphs:[`Lors du contrôle, les forces de l'ordre peuvent immobiliser le véhicule sur-le-champ et vous remettre une fiche d'immobilisation. Sans régularisation, il peut partir en fourrière au bout de 48 heures - et les frais tombent chaque jour.`],relatedLink:{text:`Voiture immobilisée ? Suivez notre guide complet pour la récupérer`,href:`/articles/voiture-immobilisee-defaut-assurance`}},{type:`text`,heading:`Que faire immédiatement`,paragraphs:[`La priorité est simple : vous remettre en règle. Une assurance auto temporaire couvre votre véhicule de 1 à 90 jours avec la responsabilité civile obligatoire, et vous fournit une attestation immédiate par email. Vous pouvez la présenter tout de suite à l'agent, ou l'utiliser pour lever une immobilisation et récupérer votre véhicule.`],relatedLink:{text:`Assurance auto temporaire immédiate en ligne : le détail minute par minute`,href:`/articles/assurance-auto-temporaire-immediate-en-ligne`}},{type:`timeline`,heading:`Comment se remettre en règle en 5 minutes`,steps:[{num:1,title:`Faites votre devis en ligne`,body:`Indiquez le type de véhicule et la durée souhaitée (de 1 à 90 jours).`},{num:2,title:`Souscrivez`,body:`Paiement sécurisé par carte bancaire, sans engagement.`},{num:3,title:`Recevez votre attestation immédiatement`,body:`Mémo Véhicule Assuré et carte internationale d'assurance automobile disponibles immédiatement par email.`},{num:4,title:`Reprenez la route en règle`,body:`Présentez votre attestation à l'agent, au commissariat, ou utilisez-la pour lever l'immobilisation.`}]},{type:`text`,heading:`Qui peut souscrire ?`,paragraphs:[`L'assurance temporaire AssuTempo couvre la grande majorité des cas (oubli de renouvellement, prélèvement rejeté, véhicule récemment acheté), sous conditions habituelles : au moins 20 ans, permis depuis plus de 2 ans, profil sans antécédents lourds. Le devis affiche immédiatement votre éligibilité, et l'équipe répond au téléphone en cas de doute.`]},{type:`text`,heading:`En résumé`,paragraphs:[`Rouler sans assurance coûte cher et expose à de lourdes peines, mais se régularise en quelques minutes. Le bon réflexe : souscrire immédiatement une assurance temporaire pour obtenir une attestation valable, présentable sur-le-champ. Plus vite vous agissez, moins ça coûte.`,`Si le contrôle a lieu la nuit ou un dimanche, vous n'êtes pas obligé d'attendre la réouverture des guichets pour vous mettre en règle : le Guichet de Nuit AssuTempo prépare les contrats de 21h à 9h et toute la journée du dimanche.`],relatedLink:{text:`Régulariser la nuit ou le dimanche : le Guichet de Nuit`,href:`/guichet-de-nuit`}}],faqItems:[{q:`Quelle amende risque-t-on en roulant sans assurance ?`,a:`Une amende forfaitaire délictuelle de 500 € (400 € minorée, 1 000 € majorée) à la première constatation, jusqu'à 3 750 € devant le tribunal, et 7 500 € en cas de récidive dans les 5 ans.`},{q:`Perd-on des points pour défaut d'assurance ?`,a:`Non. Ce n'est pas une infraction à points, mais elle expose à des peines complémentaires (suspension de permis, confiscation, etc.).`},{q:`La police peut-elle immobiliser ma voiture lors du contrôle ?`,a:`Oui, sur-le-champ. Sans régularisation, le véhicule peut partir en fourrière au bout de 48 heures.`},{q:`Comment se remettre en règle rapidement ?`,a:`En souscrivant une assurance, y compris une assurance temporaire dès 1 jour, qui délivre une attestation immédiate.`},{q:`Le défaut d'assurance va-t-il sur mon casier judiciaire ?`,a:`En cas de condamnation par un tribunal, oui, généralement au bulletin n°1, accessible aux seules autorités judiciaires.`},{q:`Peut-on souscrire une assurance temporaire après un contrôle ?`,a:`Oui, en ligne en quelques minutes, avec attestation immédiate par email.`}]}}));function s(){return(0,c.jsx)(r,{data:a})}var c;e((()=>{n(),o(),c=t()}))();export{s as default};